python - <<'PY'
import sys,numpy as np
sys.path.insert(0,'/opt/tools');from rcb_client import Robot
r=Robot();o=r.get_obs(cameras=['over_shoulder_left_camera'],video='none');c=o.meta['cameras']['over_shoulder_left_camera'];E=np.array(c['extrinsic_cv']);K=np.array(c['intrinsic_cv']);tcp=np.array([.175,.222,.245]);
def proj(p):
 c=E@np.r_[p,1];v=K@c;return np.round(v[:2]/v[2],1)
print('tcp',proj(tcp));
for name,axis in [('localx',[0,-1,0]),('localy',[-1,0,0])]:
 print(name,proj(tcp+.0425*np.array(axis)),proj(tcp-.0425*np.array(axis)))
